package design

import (
	"bytes"
	"compress/gzip"
	"encoding/binary"
	"io"
	"math"
	"strings"
	"sync"
	"unicode/utf8"

	_ "embed"
)

// Glyph advances and pair adjustments for the kit typefaces, generated by
// kit/gen/metrics.mjs from the same woff2 files the app embeds. Widths are
// in font units; multiply by size/unitsPerEm to get pixels. Pair
// adjustments include kerning and the ligatures fontkit applies, which is
// what Chromium's measureText does for these faces.

//go:embed kit/metrics.bin.gz
var metricsGz []byte

type fontWeight struct {
	upem int
	adv  map[rune]int
	pair map[uint32]int
}

var (
	metricsOnce sync.Once
	metrics     map[string]map[int]*fontWeight
	metricsErr  error
)

func loadMetrics() {
	metricsOnce.Do(func() {
		metrics, metricsErr = parseMetrics(metricsGz)
	})
}

func parseMetrics(gz []byte) (map[string]map[int]*fontWeight, error) {
	r, err := gzip.NewReader(bytes.NewReader(gz))
	if err != nil {
		return nil, err
	}
	raw, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	rd := bytes.NewReader(raw)
	magic := make([]byte, 4)
	if _, err := io.ReadFull(rd, magic); err != nil {
		return nil, err
	}
	if string(magic) != "ATLM" {
		return nil, io.ErrUnexpectedEOF
	}
	var version uint8
	if err := binary.Read(rd, binary.LittleEndian, &version); err != nil {
		return nil, err
	}
	var nFonts uint16
	if err := binary.Read(rd, binary.LittleEndian, &nFonts); err != nil {
		return nil, err
	}
	out := make(map[string]map[int]*fontWeight, nFonts)
	for range nFonts {
		var nameLen uint8
		if err := binary.Read(rd, binary.LittleEndian, &nameLen); err != nil {
			return nil, err
		}
		name := make([]byte, nameLen)
		if _, err := io.ReadFull(rd, name); err != nil {
			return nil, err
		}
		var nWeights uint8
		if err := binary.Read(rd, binary.LittleEndian, &nWeights); err != nil {
			return nil, err
		}
		weights := make(map[int]*fontWeight, nWeights)
		for range nWeights {
			var weight, upem, nAdv uint16
			if err := binary.Read(rd, binary.LittleEndian, &weight); err != nil {
				return nil, err
			}
			if err := binary.Read(rd, binary.LittleEndian, &upem); err != nil {
				return nil, err
			}
			if err := binary.Read(rd, binary.LittleEndian, &nAdv); err != nil {
				return nil, err
			}
			fw := &fontWeight{upem: int(upem), adv: make(map[rune]int, nAdv), pair: map[uint32]int{}}
			for range nAdv {
				var cp, adv uint16
				if err := binary.Read(rd, binary.LittleEndian, &cp); err != nil {
					return nil, err
				}
				if err := binary.Read(rd, binary.LittleEndian, &adv); err != nil {
					return nil, err
				}
				fw.adv[rune(cp)] = int(adv)
			}
			var nPairs uint16
			if err := binary.Read(rd, binary.LittleEndian, &nPairs); err != nil {
				return nil, err
			}
			fw.pair = make(map[uint32]int, nPairs)
			for range nPairs {
				var a, b uint16
				var delta int16
				if err := binary.Read(rd, binary.LittleEndian, &a); err != nil {
					return nil, err
				}
				if err := binary.Read(rd, binary.LittleEndian, &b); err != nil {
					return nil, err
				}
				if err := binary.Read(rd, binary.LittleEndian, &delta); err != nil {
					return nil, err
				}
				fw.pair[uint32(a)<<16|uint32(b)] = int(delta)
			}
			weights[int(weight)] = fw
		}
		out[string(name)] = weights
	}
	return out, nil
}

func nearestWeight(weight int) int {
	best, dist := 400, 1<<30
	for _, c := range []int{400, 500, 600, 700} {
		d := weight - c
		if d < 0 {
			d = -d
		}
		if d < dist {
			dist, best = d, c
		}
	}
	return best
}

func faceFor(family string, weight int) *fontWeight {
	loadMetrics()
	if metricsErr != nil {
		return nil
	}
	family = strings.TrimSpace(family)
	family = strings.TrimSuffix(family, " Variable")
	weights := metrics[family]
	if weights == nil {
		return nil
	}
	if fw := weights[weight]; fw != nil {
		return fw
	}
	return weights[nearestWeight(weight)]
}

// TextWidth is the width of text in pixels for a kit typeface, including
// letter spacing added once per character (the same way the canvas does).
// An unknown family falls back to the flat 0.55em estimate.
func TextWidth(family string, weight int, size, letterSpacing float64, text string) float64 {
	if text == "" || size <= 0 {
		return 0
	}
	fw := faceFor(family, weight)
	if fw == nil || fw.upem <= 0 {
		return float64(utf8.RuneCountInString(text)) * (size*glyphWidth + letterSpacing)
	}
	scale := size / float64(fw.upem)
	width := 0.0
	var prev rune
	seen := false
	for _, r := range text {
		adv, ok := fw.adv[r]
		if !ok {
			adv = fw.upem * 55 / 100
		}
		width += float64(adv)*scale + letterSpacing
		if seen {
			width += float64(fw.pair[uint32(prev)<<16|uint32(r)]) * scale
		}
		prev = r
		seen = true
	}
	if width < 0 {
		return 0
	}
	return width
}

// displayText applies a text node's upper/lower transform. The canvas
// measures the transformed string.
func displayText(n *Node) string {
	s := n.TextValue()
	switch n.Transform {
	case "upper":
		return strings.ToUpper(s)
	case "lower":
		return strings.ToLower(s)
	default:
		return s
	}
}

func textWidthOf(n *Node, text string) float64 {
	size := 16.0
	family := "Inter"
	weight := 400
	if n.Font != nil {
		if n.Font.Size > 0 {
			size = n.Font.Size
		}
		if n.Font.Family != "" {
			family = n.Font.Family
		}
		if n.Font.Weight > 0 {
			weight = n.Font.Weight
		}
	}
	spacing := 0.0
	if n.LetterSpacing != nil {
		spacing = *n.LetterSpacing
	}
	return TextWidth(family, weight, size, spacing, text)
}

// wrapParagraph breaks one paragraph the way the canvas does: on spaces
// first, then between letters when a word is wider than the line.
func wrapParagraph(n *Node, paragraph string, maxW float64) []string {
	if paragraph == "" {
		return []string{""}
	}
	var lines []string
	line := ""
	push := func(s string) {
		lines = append(lines, strings.TrimRight(s, " \t"))
	}
	for _, word := range splitKeepingSpace(paragraph) {
		if word == "" {
			continue
		}
		next := line + word
		if line == "" || textWidthOf(n, strings.TrimRight(next, " \t")) <= maxW+0.01 {
			line = next
			continue
		}
		if strings.TrimSpace(word) == "" {
			push(line)
			line = ""
			continue
		}
		push(line)
		line = ""
		chunk := ""
		for _, ch := range word {
			if chunk != "" && textWidthOf(n, chunk+string(ch)) > maxW && textWidthOf(n, chunk) > 0 {
				push(chunk)
				chunk = ""
			}
			chunk += string(ch)
		}
		line = chunk
	}
	push(line)
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

func splitKeepingSpace(s string) []string {
	var out []string
	var b strings.Builder
	var space bool
	flush := func() {
		if b.Len() == 0 {
			return
		}
		out = append(out, b.String())
		b.Reset()
	}
	for _, r := range s {
		isSpace := r == ' ' || r == '\t'
		if b.Len() > 0 && isSpace != space {
			flush()
		}
		space = isSpace
		b.WriteRune(r)
	}
	flush()
	return out
}

// ceilPx matches the canvas, which stores text boxes in whole pixels.
func ceilPx(v float64) float64 {
	return math.Ceil(v - 1e-9)
}
